-- Math 11.1: two random multiple-choice mini tests (Extremalprobleme, Funktionsgleichungen gesucht).
-- 8 questions drawn per attempt from a pool of 14 / 16. Safe to run more than once.

insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q01', 'math', 'Extremalprobleme', 'single', 'Was beschreibt bei einem Extremalproblem die Hauptbedingung?', '["Den Zusammenhang zwischen den Variablen, der fest vorgegeben ist", "Die Größe, die maximal oder minimal werden soll, als Formel", "Den Bereich, in dem x liegen darf", "Die erste Ableitung der Zielfunktion"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 1}'::jsonb, array['Die Hauptbedingung ist die Formel für die Größe, die optimiert werden soll (z. B. A = a · b).', 'Der feste Zusammenhang zwischen den Variablen ist die Nebenbedingung.']::text[] from public.questions where key = 'math111-ex-q01'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q02', 'math', 'Extremalprobleme', 'single', 'Wozu braucht man die Nebenbedingung?', '["Um eine Variable durch die andere auszudrücken", "Um die Ableitung zu berechnen", "Um zu prüfen, ob ein Maximum vorliegt", "Um den Funktionswert am Rand zu berechnen"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 0}'::jsonb, array['Die Hauptbedingung hat meist zwei Variablen (z. B. a und b).', 'Mit der Nebenbedingung (z. B. 2a + 2b = 40) stellt man nach einer Variablen um und setzt ein – so entsteht die Zielfunktion mit nur einer Variablen.']::text[] from public.questions where key = 'math111-ex-q02'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q03', 'math', 'Extremalprobleme', 'single', 'Ein Rechteck hat den Umfang 40 cm. Eine Seite ist x cm lang. Welche Zielfunktion beschreibt den Flächeninhalt?', '["A(x) = x · (40 − x)", "A(x) = 2x + 2(20 − x)", "A(x) = x² + 20x", "A(x) = x · (20 − x)"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 3}'::jsonb, array['Nebenbedingung: 2x + 2b = 40 ⇒ b = 20 − x.', 'Hauptbedingung: A = x · b ⇒ A(x) = x · (20 − x) = 20x − x².']::text[] from public.questions where key = 'math111-ex-q03'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q04', 'math', 'Extremalprobleme', 'single', 'Für welches x ist A(x) = x · (20 − x) maximal?', '["x = 5", "x = 20", "x = 10", "x = 15"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 2}'::jsonb, array['A(x) = 20x − x² ⇒ A′(x) = 20 − 2x.', 'A′(x) = 0 ⇒ x = 10. A″(x) = −2 < 0 ⇒ Maximum.']::text[] from public.questions where key = 'math111-ex-q04'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q05', 'math', 'Extremalprobleme', 'single', 'Wie groß ist der maximale Flächeninhalt eines Rechtecks mit Umfang 40 cm?', '["400 cm²", "100 cm²", "200 cm²", "80 cm²"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 1}'::jsonb, array['Maximum bei x = 10 (siehe A′(x) = 20 − 2x = 0).', 'A(10) = 10 · (20 − 10) = 100 cm² – das Rechteck ist ein Quadrat.']::text[] from public.questions where key = 'math111-ex-q05'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-ex-q06', 'math', 'Extremalprobleme', 'single', 'Zwei positive Zahlen haben die Summe 12. Wann ist ihr Produkt am größten?', '["Wenn beide Zahlen 6 sind", "Wenn eine Zahl 12 und die andere 0 ist", "Wenn die Zahlen 4 und 8 sind", "Wenn die Zahlen 3 und 9 sind"]'::jsonb, 1)
  on conflict (key) do update set subject = excluded.subject, topic = excluded.topic, type = excluded.type, prompt = excluded.prompt, options = excluded.options, points = excluded.points;
insert into public.question_solutions (question_id, answer, explanation) select id, '{"choice": 0}'::jsonb, array['Nebenbedingung: x + y = 12 ⇒ y = 12 − x. Zielfunktion: P(x) = x(12 − x) = 12x − x².', 'P′(x) = 12 − 2x = 0 ⇒ x = 6, also y = 6. Produkt: 36 (zum Vergleich 4 · 8 = 32).']::text[] from public.questions where key = 'math111-ex-q06'
  on conflict (question_id) do update set answer = excluded.answer, explanation = excluded.explanation;
