insert into public.questions (key, subject, topic, type, prompt, options, points) values ('math111-fg-q14', 'math', 'Funktionsgleichungen gesucht', 'single', 'Eine Parabel f(x) = ax² + bx + c geht durch (0|1), (1|0) und (2|1). Wie lautet f?', '["f(x) = x² − 2x + 1", "f(x) = −x² + 2x + 1", "f(x) = x² + 2x + 1", "f(x) = 2x² − 2x + 1"]'::jsonb, 1)
